import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * Scratch probe (Routine C, not to be committed): classifies the projected values of a DISTINCT + nested OPTIONAL query
 * by how ValuePreparer.capture treated them.
 */
class ScratchCaptureAllocationProbeTest {

	private static final String NS = "http://example.org/ns#";

	private static final String QUERY = "PREFIX : <" + NS + ">\n"
			+ "SELECT DISTINCT ?queue ?pkg ?host ?hostCluster ?hostStage ?tpHost ?tpCluster ?tpStage ?ex ?name\n"
			+ "WHERE {\n"
			+ "  ?nameIri a :Proc . ?nameIri :id ?name . ?nameIri :config ?cfg . ?cfg :mapsTo ?qoh .\n"
			+ "  ?qoh :queue ?queueIri . ?queueIri :id ?queue .\n"
			+ "  OPTIONAL { ?nameIri :pkg ?pkgIri . ?pkgIri :id ?pkg . }\n"
			+ "  OPTIONAL { ?cfg :host ?hostIri . ?hostIri :id ?host .\n"
			+ "    OPTIONAL { ?hostIri :stage ?hsIri . ?hsIri :id ?hostStage . }\n"
			+ "    OPTIONAL { ?hostIri :cluster ?hcIri . ?hcIri :id ?hostCluster . } }\n"
			+ "  OPTIONAL { ?qoh :ex ?exIri . ?exIri :id ?ex .\n"
			+ "    OPTIONAL { ?exIri :flavor ?fl . ?fl :group ?grp . ?grp :tpHost ?tpIri . ?tpIri :id ?tpHost .\n"
			+ "      OPTIONAL { ?tpIri :stage ?tsIri . ?tsIri :id ?tpStage . }\n"
			+ "      OPTIONAL { ?tpIri :cluster ?tcIri . ?tcIri :id ?tpCluster . } } }\n"
			+ "}";

	@TempDir
	File dataDir;

	@Test
	void probe() throws Exception {
		for (boolean nativeEval : new boolean[] { true, false }) {
			File dir = new File(dataDir, "native-" + nativeEval);
			dir.mkdirs();
			SailRepository repo = new SailRepository(
					new LmdbStore(dir, new LmdbStoreConfig().setNativeEvaluationEnabled(nativeEval)));
			repo.init();
			try {
				load(repo);
				// Two runs: the second sees warmed caches, like a repeated server query.
				for (int run = 0; run < 2; run++) {
					Map<String, Integer> kinds = new TreeMap<>();
					int rows = 0;
					try (RepositoryConnection c = repo.getConnection();
							TupleQueryResult r = c.prepareTupleQuery(QUERY).evaluate()) {
						while (r.hasNext()) {
							BindingSet row = r.next();
							rows++;
							row.forEach(b -> kinds.merge(classify(b.getValue()), 1, Integer::sum));
						}
					}
					System.out.println("PROBE native=" + nativeEval + " run=" + run + " rows=" + rows);
					kinds.forEach((k, v) -> System.out.println("PROBE   " + v + "\t" + k));
				}
			} finally {
				repo.shutDown();
			}
		}
	}

	private static String classify(Value value) {
		StringBuilder sb = new StringBuilder(value.getClass().getSimpleName());
		if (value instanceof PreparedLmdbValue.Prepared prepared) {
			PreparedLmdbValue.State state = prepared.state();
			LmdbValue.InternalIdentity identity = state.dictionaryProof.identity();
			sb.append(" srcId=").append(identity.id() == LmdbValue.UNKNOWN_ID ? "UNKNOWN" : "known");
			sb.append(" rev=")
					.append(identity.revision() == null ? "null"
							: identity.revision().getClass().getSimpleName());
			sb.append(" payload=").append(state.payload == null ? "cold" : state.payload.getClass().getSimpleName());
			if (state.payload instanceof Literal literal) {
				sb.append(" datatype=").append(literal.getDatatype().getClass().getSimpleName());
			}
		} else if (value instanceof LmdbValue nativeValue) {
			ValueStoreRevision revision = nativeValue.getValueStoreRevision();
			sb.append(" rev=").append(revision == null ? "null" : revision.getClass().getSimpleName());
			sb.append(" semVer=").append(nativeValue.getSemanticVersion() == LmdbValue.UNKNOWN_ID ? "UNKNOWN" : "set");
			sb.append(" init=").append(nativeValue.isInitialized());
			sb.append(" extOwned=").append(nativeValue.isExternallyOwned());
		}
		return sb.toString();
	}

	private static void load(SailRepository repo) {
		try (RepositoryConnection c = repo.getConnection()) {
			ValueFactory vf = c.getValueFactory();
			c.begin();
			for (int i = 0; i < 2000; i++) {
				IRI name = vf.createIRI(NS, "proc" + i);
				IRI cfg = vf.createIRI(NS, "cfg" + i);
				IRI qoh = vf.createIRI(NS, "qoh" + i);
				IRI queue = vf.createIRI(NS, "queue" + (i % 500));
				IRI host = vf.createIRI(NS, "host" + (i % 100));
				IRI ex = vf.createIRI(NS, "ex" + (i % 50));
				IRI tp = vf.createIRI(NS, "tp" + (i % 20));
				c.add(name, RDF.TYPE, vf.createIRI(NS, "Proc"));
				c.add(name, p(vf, "id"), vf.createLiteral("proc-" + i));
				c.add(name, p(vf, "config"), cfg);
				c.add(cfg, p(vf, "mapsTo"), qoh);
				c.add(qoh, p(vf, "queue"), queue);
				c.add(queue, p(vf, "id"), vf.createLiteral("queue-" + (i % 500)));
				if (i % 3 != 0) {
					IRI pkg = vf.createIRI(NS, "pkg" + (i % 30));
					c.add(name, p(vf, "pkg"), pkg);
					c.add(pkg, p(vf, "id"), vf.createLiteral("pkg-" + (i % 30)));
				}
				c.add(cfg, p(vf, "host"), host);
				c.add(host, p(vf, "id"), vf.createLiteral("host-" + (i % 100)));
				c.add(host, p(vf, "stage"), vf.createIRI(NS, "stage" + (i % 3)));
				c.add(vf.createIRI(NS, "stage" + (i % 3)), p(vf, "id"), vf.createLiteral("stage-" + (i % 3)));
				c.add(host, p(vf, "cluster"), vf.createIRI(NS, "cluster" + (i % 7)));
				c.add(vf.createIRI(NS, "cluster" + (i % 7)), p(vf, "id"), vf.createLiteral("cluster-" + (i % 7)));
				c.add(qoh, p(vf, "ex"), ex);
				c.add(ex, p(vf, "id"), vf.createLiteral("ex-" + (i % 50)));
				c.add(ex, p(vf, "flavor"), vf.createIRI(NS, "flavor" + (i % 50)));
				c.add(vf.createIRI(NS, "flavor" + (i % 50)), p(vf, "group"), vf.createIRI(NS, "group" + (i % 10)));
				c.add(vf.createIRI(NS, "group" + (i % 10)), p(vf, "tpHost"), tp);
				c.add(tp, p(vf, "id"), vf.createLiteral("tp-" + (i % 20)));
				c.add(tp, p(vf, "stage"), vf.createIRI(NS, "stage" + (i % 3)));
				c.add(tp, p(vf, "cluster"), vf.createIRI(NS, "cluster" + (i % 7)));
			}
			c.commit();
		}
	}

	private static IRI p(ValueFactory vf, String local) {
		return vf.createIRI(NS, local);
	}
}
